import React, {useState} from "react";
import {Button} from "../../index";
import {VoiceSelector} from "../VoiceSelector/VoiceSelector";
import useSpeechSynthesis from "../../hooks/useSpeechSynthesis";
import {useAvailableVoices} from "../../hooks/useAvailableVoices";

const TextToSpeech = () => {
    const [text, setText] = useState("Hello my dear friends");
    const {speak,availableVoices,setCurrentVoice, currentIndex} = useSpeechSynthesis();
    const voiceList=useAvailableVoices()
    if (!window.speechSynthesis) {
        console.error("SpeechSynthesis API не поддерживается в этом браузере.");
        return;
    }
    const handleSpeak = () => {
        speak({text})
    };


    return (
        <>
            <div style={{padding: "20px", margin: "auto"}}>
                <h2>Text to Speech Converter</h2>
                <textarea
                    rows="5"
                    style={{width: "100%", marginBottom: "10px"}}
                    placeholder="Enter text here..."
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                />

                <VoiceSelector setCurrentVoice={setCurrentVoice} currentIndex={currentIndex} availableVoices={availableVoices} />
                <h3>index {currentIndex}</h3>
                <h4>{voiceList[currentIndex]?.name}</h4>
                <Button onAction={handleSpeak}>
                    <div style={{fontSize: "1.5rem"}}>Speak</div>
                </Button>

            </div>
        </>
    );
};

export {TextToSpeech};
