import React, {useEffect} from 'react';

import css from "./ShowText.module.css";

const ShowText = ({text,onEnd}) => {

    useEffect(() => {
        if(onEnd){
            onEnd();
        }
    }, [onEnd]);

    return (
        <div className={css.show_text}>
            {text}
        </div>
    );
};

export  {ShowText};