import {useCallback, useEffect, useRef, useState} from "react";
import { ProgressBar} from "../../../shared";

import {usePlayerScenarioManager} from "../hooks/usePlayerScenarioManager";
import {RepeatManager} from "../components/RepeatManager/RepeatManager";


const withRepeatDelayVisible = (WrappedComponent) => {
    return function RepeatDelayVisible({delay, repeatCount = 1, onEnd: handleOnEnd, ...props}) {
        const [remainingRepeats, setRemainingRepeats] = useState(repeatCount);
        const refIntervalId = useRef(null);
        const [flag, setFlag] = useState(0);
        const [state] = usePlayerScenarioManager()
        const {isPaused} = state

        const nextWithDelay = useCallback(() => {
            refIntervalId.current = setInterval(() => {
                setRemainingRepeats((prev) => prev - 0.5); // Каждое переключение (показ/скрытие) считается за 0.5
            }, delay * 1000);
        }, [delay])

        useEffect(() => {
            if (remainingRepeats < 1) {
                // Если количество повторов закончилось, вызываем callback
                if (handleOnEnd) {
                    handleOnEnd();
                }
                return;
            }

            if (!isPaused && flag === 2) nextWithDelay()

            return () => clearInterval(refIntervalId.current);
        }, [remainingRepeats, delay, handleOnEnd, flag, nextWithDelay]);


        const onEnd = () => {
            setFlag(2)
        }
        const onStart = () => {
            setFlag(1)
        }


        return (
            <div style={{position: "relative"}}>
                <WrappedComponent {...{...props, repeat: Math.ceil(remainingRepeats), onEnd, onStart}} />
                <RepeatManager count={Math.ceil(remainingRepeats) - 1}
                               setCount={setRemainingRepeats}
                               style={{position: "absolute", bottom: "0.8rem"}}/>

                <div style={{height: "1.5rem",marginTop:"1rem"}}>
                    <ProgressBar isVisible={flag === 2} delay={delay}/>
                </div>

            </div>
        );
    };

}

export {withRepeatDelayVisible}