import React, {useEffect, useRef, useState} from 'react';

import css from "./ProgressBar.module.css"

const ProgressBar = ({isVisible, width = "100%", delay}) => {
    const [widthLine, setWidthLine] = useState(100);
    const refIntervalId = useRef(null)
    useEffect(() => {
        if (isVisible) {
            setWidthLine(100)
            refIntervalId.current = setInterval(() => {
                setWidthLine(prev => Math.max(prev - 0.1, 0))
            }, delay)
        } else {
            clearInterval(refIntervalId.current);
            setWidthLine(0)
        }

        return () => {
            if (refIntervalId.current) clearInterval(refIntervalId.current)
        }
    }, [isVisible, delay]);

    if (!isVisible) return null

    return (
        <div className={css.progress_bar} style={{"--width-line": widthLine, width: width}} data-label="Pause..."></div>
    );
};

export {ProgressBar};