import React, {useState} from 'react';

import css from "./RepeatManager.module.css"
import {Button, Odometer} from "../../index";

const RepeatManager = ({count = 0, setCount, style = {}}) => {
    const [isOpen, setIsOpen] = useState(false);

    const toggleDiv = () => {
        setIsOpen(!isOpen);
    };

    const increment = () => {
        setCount(prev => prev + 1);
    };

    const decrement = () => {
        setCount(prev => prev - 1);
    };
    const styleBtn = {borderRadius: "50%", padding: "0 0.5rem",border:"1px solid var(--border-color)"}

    return (
        <div className={css.container} style={style}>

            <div className={`${css.animated_div} ${isOpen ? css.open : css.closed}`}>
                <div className={css.button_group}>
                    <Button onAction={decrement} style={styleBtn} disabled={count === 0}>
                        <div style={{fontSize: "2.5rem", padding: "0 0.5rem 0.3rem"}}>
                            -
                        </div>
                    </Button>

                    <Button onAction={toggleDiv} style={styleBtn}>
                        <Odometer number={count} className={css.odometer}/>
                    </Button>

                    <Button onAction={increment} style={styleBtn} disabled={count === 9}>
                        <div style={{fontSize: "2.5rem", padding: "0 0.2rem"}}>
                            +
                        </div>
                    </Button>

                </div>
            </div>
        </div>
    );
};

export {RepeatManager};