import {createHashRouter, Navigate} from "react-router-dom";
import {HomePage} from "../../Pages/HomePage";
import {MainLayout} from "../Components/MainLayout/MainLayout";
import { SpeechToTextPage} from "../../Pages/SpeechRecognition.page";
import {AudioPlayerPage} from "../../Pages/AudioPlayer.page";
import {TextToSpeechPage} from "../../Pages/TextToSpeech.page";
import {TmpPage} from "../../Pages/Tmp.page";
import {EnglishPage} from "../../Pages/EnglishPage";
import {UkrainianPage} from "../../Pages/UkrainianPage";




const router = createHashRouter([
    {path:"/",element:<MainLayout/>,children:[
            {index:true,element:<Navigate to={"home"} replace/>},
            {path:"home",element:<HomePage/>},
            {path:"player",element:<AudioPlayerPage/>},
            {path:"text_to_speech",element:<TextToSpeechPage/>},
            {path:"tmp",element:<TmpPage/>},
            {path:"english",element:<EnglishPage/>},
            {path:"ukrainian",element:<UkrainianPage/>},
            {path:"speech",element:<SpeechToTextPage/>},
            {path: "*", element: <h1>NoPage</h1>}
        ]}
])

export  {router};