import React from 'react';
import {usePlayerScenarioManager} from "../../../hooks/usePlayerScenarioManager";
import {ButtonPulse, HoldButton} from "../../../../../shared";
import {GrCaretNext, GrCaretPrevious} from "react-icons/gr";

import start from "../../../data/start.png"
import stop from "../../../data/stop.png"

import css from "./PlayerScenarioManager.module.css"

const PlayerScenarioManager = () => {
    const [state, setState] = usePlayerScenarioManager();
    const {currentIndex, isPaused, maxIndex} = state;

    const handleNext = () => {
        const index = Math.min(currentIndex + 1, maxIndex);
        setState({isPaused: true, currentIndex: index, currentStep: 0, stages: []})
    };

    const handlePrevious = () => {
        const index = Math.max(currentIndex - 1, 0)
        setState({isPaused: true, currentIndex: index, currentStep: 0, stages: []})
    };

    const handlePause = () => {
        setState({isPaused: !isPaused})
    };

    return (
        <div className={css.manager}>
            <HoldButton onAction={handlePrevious} disabled={currentIndex === 0}>
                <div style={{fontSize: "1.5rem", padding: "0.5rem"}}>
                    <GrCaretPrevious/>
                </div>
            </HoldButton>
            <ButtonPulse isPulse={isPaused} onAction={handlePause} backgroundColor={isPaused?"var(--success-color)":"var(--error-color)"}>
                {/*{isPaused ? <AiOutlineSound/> : <PiPauseBold/>}*/}
                {isPaused ?
                    <div style={{width: "3rem", height: "3rem", borderRadius: "50%",overflow:"hidden"}}>
                        <img style={{width: "100%", height: "auto"}} src={start} alt="Start"/>
                    </div>
                    :
                    <div style={{width: "3rem", height: "3rem", borderRadius: "50%",overflow:"hidden"}}>
                        <img style={{width: "100%", height: "auto"}} src={stop} alt="Stop"/>
                    </div>
                }
                    </ButtonPulse>
                    <HoldButton onAction={handleNext} disabled={currentIndex === maxIndex}>
                <div style={{fontSize: "1.5rem", padding: "0.5rem"}}>
                    <GrCaretNext/>
                </div>
            </HoldButton>

        </div>
    );
};

export {PlayerScenarioManager};
