import React, {useEffect, useState} from 'react';
import useSpeechSynthesis from "../../hooks/useSpeechSynthesis";
import {AiOutlineSound} from "react-icons/ai";
import {HoldButton} from "../../../../shared";

const VoiceText = ({text, lang, onEnd: handleOnEnd, onStart: handleOnStart, repeat}) => {
    const {speak} = useSpeechSynthesis();
    const [flag, setFlag] = useState(0)
    useEffect(() => {
        const onStart = () => {
            setFlag(1);
            if (handleOnStart) {
                handleOnStart()
            }
        }

        const onEnd = () => {
            setFlag(2);
            if (handleOnEnd) {
                handleOnEnd();
            }
        }

        if (flag === 0) {
            speak({text, lang, onStart, onEnd});
        }

    }, [text, lang, speak, handleOnEnd,handleOnStart, flag]);

    useEffect(() => {
        setFlag(0)
    }, [repeat])

    return (
        <HoldButton onAction={() => speak({text, lang})}>
            <div style={{
                width: "10px",
                height: "10px",
                borderRadius: "50%",
                background: flag === 1 ? "yellow" : "inherit"
            }}></div>
            <div style={{fontSize: "1.5rem", padding: "0.5rem"}}>
                <AiOutlineSound/>
            </div>
        </HoldButton>
    );
};

export {VoiceText};