import React, {useEffect} from "react";

import {Frame} from "../../Frame/Frame"
import {PlayerScenarioManager} from "../PlayerScenarioManager/PlayerScenarioManager";
import {usePlayerScenarioManager} from "../../../hooks/usePlayerScenarioManager";
import useSpeechSynthesis from "../../../hooks/useSpeechSynthesis";


const PlayerScenario = ({data,scenario}) => {
    const [state, setState] = usePlayerScenarioManager();

    const {currentStep, currentIndex, isPaused, stages} = state;
    useSpeechSynthesis()

    useEffect(() => {
        setState({maxIndex: data.length - 1})
    }, [])

    const nextStep = () => {
        // Остановить, если пауза или все элементы обработаны
        if (isPaused || currentIndex >= data.length) {
            return
        }
        // Переходим к следующему шагу сценария
        if (currentStep < scenario.length - 1) {

            setState({currentStep: currentStep + 1})
        } else {
            // Если шаги сценария закончились, переходим к следующему элементу data
            if (currentIndex < data.length - 1) {
                setState({currentIndex: currentIndex + 1, currentStep: 0, stages: []})
            }
        }
    };
    useEffect(() => {
        const getData = () => {
            const field = scenario[currentStep]?.field;
            return data[currentIndex][field]
        }
        if (isPaused || currentIndex >= data.length) return; // Остановить, если пауза или все элементы обработаны

        // Проверяем имеется ли новый Frame в stages, если Да, удаляем последний Frame массива stages
        if (stages.length === currentStep + 1) {
            stages.pop();
           setState({stages:[...stages]})
        }

        // Добавляем новый Frame при каждом новом шаге
            setState({
                stages: [...stages,
                    <Frame
                        key={`${currentIndex}-${currentStep}`} // Уникальный ключ для каждого Frame
                        actions={scenario[currentStep]}
                        data={getData()}
                        onEnd={nextStep}
                    />
                ]
            })

    }, [currentStep, currentIndex, isPaused, scenario]); // Обновляем при изменении шага или индекса

    return <div style={{height: "100%", position: "relative", border: "1px solid red"}}>
        {stages}
        <PlayerScenarioManager/>
    </div>
};

export {PlayerScenario};
