import React from 'react';
import {withRepeatDelayVisible} from "../../hoc/withRepeatDelayVisible";
import {VoiceText} from "../VoiceText/VoiceText";
import {ShowText} from "../ShowText/ShowText";
import {CardVoiceText} from "../CardVoiceText/CardVoiceText";

const Frame = ({actions, data, onEnd}) => {
    if (!actions) return;

    const {delay, type, repeats} = actions;

    let RenderComponent = null;
    switch (type) {
        case "show":
            RenderComponent = ShowText
            break;
        case "sound":
            RenderComponent = withRepeatDelayVisible(VoiceText)
            break;
        case "card":
            RenderComponent = withRepeatDelayVisible(CardVoiceText)
            break;
        default:
            console.log(`Sorry, something went wrong.`);
    }


    const {title, voice} = data;

    return (
        <div>
            <RenderComponent delay={delay} repeatCount={repeats} onEnd={onEnd} text={title} lang={voice} />
        </div>
    );
};

export {Frame};