import React, {useState} from 'react';
import {Odometer} from "../shared";
import {RepeatManager} from "../modules/text_to_speech/components/RepeatManager/RepeatManager";

const HomePage = () => {
    const [count, setCount] = useState(0);
    const handleClick = () => {
        setCount(prevState => prevState + 1)
    }

    return (
        <>
            <h1> HomePage </h1>
            <Odometer number={count.toString()}/>
            <button style={{fontSize: "2rem", color: "white", border: "1px solid red"}} onClick={handleClick}>+</button>

            <RepeatManager/>
        </>

    );
};

export {HomePage};