import React, {useEffect, useState} from 'react';
import useSpeechSynthesis from "../../hooks/useSpeechSynthesis";
import {HoldButton} from "../../../../shared";

import css from "./CardVoiceText.module.css"
import {usePlayerScenarioManager} from "../../hooks/usePlayerScenarioManager";
import {AiOutlineSound} from "react-icons/ai";

const CardVoiceText = ({text, lang, onEnd: handleOnEnd, onStart: handleOnStart, repeat}) => {
    const {speak} = useSpeechSynthesis();
    const [state, setState] = usePlayerScenarioManager()
    const [flag, setFlag] = useState(0)
    useEffect(() => {
        const onStart = () => {
            setFlag(1);
            if (handleOnStart) {
                handleOnStart()
            }
        }

        const onEnd = () => {
            setFlag(2);
            if (handleOnEnd) {
                handleOnEnd();
            }
        }

        if (flag === 0) {
            speak({text, lang, onStart, onEnd});
        }

    }, [text, lang, speak, handleOnEnd, handleOnStart, flag]);

    useEffect(() => {
        setFlag(0)
    }, [repeat])

    const handleClick = () => {
        setState({isPaused: true});
        speak({text, lang})
    }

    return (

        <div className={css.card}>
            <div className={css.text}>{text} {lang}</div>
            <HoldButton onAction={handleClick} className={css.button} >
                <div className={css.text}>
                    <div style={{fontSize: "1.5rem", padding: "0.5rem"}}>
                        <AiOutlineSound/>
                    </div>
                </div>
            </HoldButton>
        </div>
    );
};

export {CardVoiceText};