import {useSyncExternalStore} from "react";

const store = {
    state: {
        currentIndex: 0,
        currentStep: 0,
        isPaused: true,
        maxIndex: 0,
        stages: []
    },
    subscribers: new Set(),

    getState() {
        return this.state;
    },

    setState(newState) {
        this.state = {...this.state, ...newState};
        this.subscribers.forEach((callback) => callback());
    },

    subscribe(callback) {
        this.subscribers.add(callback);
        return () => {
            this.subscribers.delete(callback);
        };
    },
};


const usePlayerScenarioManager = () => {
    const state = useSyncExternalStore(
        (callback) => store.subscribe(callback),
        () => store.getState()
    );
    const setState = (newState) => store.setState(newState)
    return [state, setState]
}

export {usePlayerScenarioManager}