import {useCallback, useRef, useState} from "react";
import {useAvailableVoices} from "./useAvailableVoices";

const useSpeechSynthesis = () => {
    const synth = window.speechSynthesis;
    const refVoices = useRef([]);
    refVoices.current = useAvailableVoices();
    const availableVoices = refVoices.current.map((v, index) => ({
        lang: v.lang,
        name: v.name,
        index,
    })).filter(v => ["uk", "en", "ru"].includes(v.lang.slice(0, 2)))
        .sort((a, b) => a.lang.localeCompare(b.lang));

    const [index, setIndex] = useState(0);

    const setCurrentVoice = useCallback(({index, lang}) => {
        if (index !== undefined) {
            setIndex(index);
        } else if (lang) {
            const voice = availableVoices.find(v => v.lang === lang);
            if (voice) {
                setIndex(voice.index);
            }
        }
    }, [availableVoices]);

    const speak = useCallback(({text, lang, onStart, onEnd, isPause}) => {
        const utterance = new SpeechSynthesisUtterance(text);
        if (lang) {
            // const voiceIndex =availableVoices.find(v => v.lang === lang).index;
            const voiceIndex = availableVoices.find(v => v.lang === lang)?.index;
            utterance.voice = refVoices.current[voiceIndex];
        } else {
            utterance.voice = refVoices.current[index];
        }
        synth.speak(utterance);

        utterance.onend = () => {
            if (typeof onEnd === "function") onEnd()
            // console.log("Синтез речи завершен.");
        };
        utterance.onstart = () => {
            if (typeof onStart === "function") onStart()
            // console.log("Синтез речи стартовал.");
        };

        utterance.onerror = (event) => {
            console.error("Ошибка синтеза речи:", event.error);
        };
    }, [index, synth, availableVoices]);


    return {
        availableVoices,
        currentIndex: index,
        setCurrentVoice,
        speak,
    };
};

export default useSpeechSynthesis;
